package tax

import "testing"

func TestLineVAT(t *testing.T) {
	tests := []struct {
		name   string
		net    int64
		rateBP int
		want   int64
	}{
		{"zero", 0, 2000, 0},
		{"standard 20%", 1000, 2000, 200},
		{"half rounds up", 25, 2000, 5},
		{"just below half", 24, 2000, 4},
		{"reduced 5%", 999, 500, 50},
		{"zero rate", 1999, 0, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := LineVAT(tt.net, tt.rateBP); got != tt.want {
				t.Errorf("LineVAT(%d, %d) = %d, want %d", tt.net, tt.rateBP, got, tt.want)
			}
		})
	}
}

func TestInvoiceVAT(t *testing.T) {
	lines := []Line{{NetMinor: 1000, RateBP: 2000}, {NetMinor: 333, RateBP: 2000}}
	tests := []struct {
		name  string
		buyer Party
		want  int64
	}{
		{"domestic", Party{Country: SellerCountry}, 267},
		{"reverse charge cross-border", Party{Country: "DE", ReverseCharge: true}, 0},
		{"reverse charge flag but domestic", Party{Country: SellerCountry, ReverseCharge: true}, 267},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := InvoiceVAT(lines, tt.buyer); got != tt.want {
				t.Errorf("got %d, want %d", got, tt.want)
			}
		})
	}
}
